note_models.css:
.card {
 font-family: 'Sorts Mill Goudy', Garamond, Georgia, 'Times New Roman', serif;
 text-align: justify;
}

img {
 width: 100%;
 max-width: 100%;
  display: block;

}


.lang_en {display: none;}

.lang_de {}

.lang_fr {display: none;}

.lang_pl {display: none;}

.lang_la {}

.description {
	font-size: 1.5em;
	max-width: 600px;
   margin: 0 auto;
}

.mobile .description {
	font-size: 1em;
}

.answer, .question {
	position: absolute; 
	left: 0%; 
	background: rgba(255,255,255,0.7); 
	color: black; 
	margin: 1% 1%; 
	padding: 1%;
	border-radius: 3vw;
	font-size: 2.5vw;
    backdrop-filter: blur(0.2vw);
    -webkit-backdrop-filter: blur(0.2vw); /* Safari */
}

.answer .lang, .question .lang{
	font-size: 1.5vw;
	color: rgba(0,0,0,0.5);
}

.danger {
	color: orange;
	opacity: 50%;
	font-size: 0.8em;
}

.mobile .answer .lang, .mobile .question .lang{
	font-size: 0.5em;
	color: inherit;
	opacity: 50%;
}


.answer {
	top: 0%;
}

.question {
	bottom: 0%;
}

.mobile .answer, .mobile .question {
	position: relative;
	background: inherit;
	color: inherit;
	font-size: 1.2em;
	margin: inherit;
	padding: inherit;
	border: none;
	width: 100%;
	margin: 5px 0px;
	text-align: left;
    margin-bottom: auto;
}

.mobile .answer div {
	margin: 0.5em 0em;
}

.description {
	margin-bottom: 1em;
}

@media screen and (orientation: landscape) {
  body.mobile {
    display: flex;
    justify-content: center;
  }
  .mobile .card {
    width: 65vw;
    margin: auto;
  }
  .mobile .lang-indicator {
    position: absolute;
    bottom: -1vw;
    left: 1%;
    font-size: 1.5vw;
    color: rgba(0,0,0,0.5);
  }
  .mobile .answer div  {
 	  margin: 1em;
  }
  .mobile .answer, .mobile .question {
    position: absolute;
    color: black;
    margin: 0% 0%;
    padding: 0;
    border: none;
    font-size: 2vw;
    width: auto;
    top: 0.3vw;
    padding-left: 1vw;
    padding-right: 0.5vw;
    border-radius: 0 1vw 1vw 0;
    bottom: auto;
  }
  .mobile .answer .lang, .mobile .question .lang {
    color: rgba(0,0,0,0.5);
    font-size: 1vw;
  }
  .mobile .answer div, .mobile .question div {
    margin: 0;
  }
}
